<template>
  <section class="document-library">
    <header class="library-hero"><div><p class="eyebrow">Plot Twist CO · Company essentials</p><h1>Your policies.<br /><span>A place to grow.</span></h1><p class="hero-description">A shared starting point. Handbooks and guides that become each company’s own.</p></div><div class="package-card"><span class="package-label">Included in Basic</span><strong>Company document library</strong><p>Branded editions · Section editing<br />Search &amp; answers · Update history</p><small>Also included in Premium and Premium Plus.</small></div></header>
    <div class="library-intro"><div><h2>Start with a strong foundation</h2><p>Plot Twist CO maintains the templates. Each company reviews, customizes and publishes its own edition.</p></div><span class="library-count">{{ assignedCount }} company editions</span></div>
    <div class="library-columns">
      <div class="template-list"><article v-for="template in catalog" :key="template.key" class="template-card"><span class="document-symbol" aria-hidden="true">Aa<span>01</span></span><p class="eyebrow">{{ template.owner }} · Template {{ template.version }}</p><h3>{{ template.title }}</h3><p>{{ template.description }}</p><div class="template-details"><span>{{ template.sectionCount }} sections</span><span>{{ template.requiredSections.length }} company setup topics</span></div><p class="template-note">Company history, service programs, pay, benefits and local requirements belong to the company edition.</p></article><p class="library-footnote">This library is the home for your document package. The Provider’s Guide is also available in each company workspace, with clinical role guidance, searchable sections and source-based answers. New document types can join the package as it grows.</p></div>
      <section class="company-list" aria-label="Company document editions"><div class="company-list-heading"><h2>Company editions</h2><label><span class="sr-only">Find a company</span><input v-model="query" type="search" placeholder="Find a company…" /></label></div><p v-if="!filtered.length" class="empty">{{ companies.length ? 'No companies match this search.' : 'No companies are available for your account.' }}</p><button v-for="company in filtered" :key="company.id" type="button" :class="['company-row', { selected: Number(selectedId) === Number(company.id) }]" :aria-pressed="Number(selectedId) === Number(company.id)" @click="$emit('select', company.id)"><span class="company-initial" aria-hidden="true">{{ company.name.slice(0, 1) }}</span><span class="company-name"><strong>{{ company.name }}</strong><small>{{ company.hasOwnedHandbook ? 'Original company handbook' : company.assignment_id ? `Plot Twist CO template ${company.template_version} · Basic package` : company.published_version_id || company.draft_version_number ? 'Existing company handbook' : 'Ready for document setup' }}</small></span><span class="company-status">{{ company.published_version_id ? `Published v${company.published_version_number}` : company.draft_version_number ? `Draft v${company.draft_version_number}` : company.assignment_id ? 'Assigned · Prepare draft' : company.hasOwnedHandbook ? 'Content ready' : 'Not assigned' }}</span></button></section>
    </div>
    <section v-if="selected" class="company-workspace" :aria-label="`${selected.name} documents`"><header class="company-workspace-head"><div><p class="eyebrow">Company workspace</p><h2>{{ selected.name }}</h2><p v-if="selected.assignment_id">Template {{ selected.template_version }} · {{ selected.publishedTemplateVersion ? `Published from template ${selected.publishedTemplateVersion}` : 'No template edition published yet' }}</p></div><span class="edition-label">{{ selected.hasOwnedHandbook ? 'Original company edition' : 'Company edition' }}</span></header>
      <template v-if="canOpen(selected)"><slot name="workspace" :company="selected" /></template>
      <div v-else class="assign-panel"><h3>Make the handbook part of this company's package</h3><p>Assign the general template, complete the company details and review the draft before making it available to staff.</p><button v-if="canAssign" type="button" class="assign-button" :disabled="busy" @click="$emit('assign', { agencyId: selected.id, key: catalog[0].key, version: catalog[0].version })">{{ busy ? 'Assigning…' : 'Include workplace handbook · Basic' }}</button><p v-else>The platform administrator can add this handbook to your company's package.</p><small>Assignment creates an independent company edition. It does not publish policies or change subscription prices.</small></div>
    </section>
  </section>
</template>
<script setup>
import { computed, ref } from 'vue';
const props = defineProps({ catalog: { type: Array, default: () => [] }, companies: { type: Array, default: () => [] }, selectedId: { type: [Number, String], default: null }, canAssign: Boolean, busy: Boolean });
defineEmits(['select', 'assign']);
const query = ref('');
const canOpen = company => company.assignment_id || company.hasOwnedHandbook || company.published_version_id || company.draft_version_number;
const filtered = computed(() => props.companies.filter(c => `${c.name} ${c.slug}`.toLowerCase().includes(query.value.trim().toLowerCase())));
const assignedCount = computed(() => props.companies.filter(canOpen).length);
const selected = computed(() => props.companies.find(c => Number(c.id) === Number(props.selectedId)));
</script>
